; Auto-generated by scripts/generate-palette-transitions.js from src/games/lightsout/palettes/.
; Do not edit by hand -- regenerate instead.
;
; Every palette has one fixed IIgs slot layout: the IIgs palette 0 slot that each of the 32 NES
; palette RAM entries ($3F00-$3F1F) is shown in.  The layouts are chosen together, so that the
; background groups that keep the same slots across the transitions don't need their tiles
; redrawn (a group whose slots change has to be recompiled with the new swizzle table).
;
; Requires: NES_ColorToIIgs_X, NES_SetPaletteMap, RefreshPPUAttributes, PPU_MEM, SHR_PALETTES

; Swizzle tables, in the PALDATA segment (palettes.s)
PAL_GAME_SWIZZLE EXT

; Palette ids, word-aligned so they index the tables below directly.  0 = no palette.
PAL_GAME equ 2

; Layouts (NES color -> [slots] per group; *reserved, ~shown as):
;   game
;     BG0 $0F $00 $0F $10 -> [0,1,0,2]
;     BG1 $0F $00 $16 $10 -> [0,1,3,2]
;     BG2 $0F $0F $0F $0F -> [0,0,0,0]
;     BG3 $0F $0F $0F $0F -> [0,0,0,0]
;     SP0 $0F $0F $00 $30 -> [0,0,1,4]
;     SP1 $0F $0F $0F $0F -> [0,0,0,0]
;     SP2 $0F $0F $0F $0F -> [0,0,0,0]
;     SP3 $0F $0F $0F $0F -> [0,0,0,0]

            mx    %00

; UpdatePalette
;
; X = from palette id (PAL_*, or 0 for none), Y = to palette id
;
; Switches the swizzle tables to the new palette, loads its colors (LoadPaletteColors), then redraws
; the background groups whose slots changed.  Call from the GS task (it redraws tiles).
UpdatePalette
            lda   BG_UPDATE_MASKS,x
            pha
            lda   (1,s),y
            sta   1,s                 ; 1,s = groups to redraw

            phy
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jsr   NES_SetPaletteMap
            ply

            jsr   LoadPaletteColors
            pla
            jmp   RefreshPPUAttributes

; LoadPaletteColors
;
; Y = palette id.  Loads IIgs palette 0 from the current NES palette RAM, in the palette's layout,
; so the colors the game changes on the fly (fades, color cycling, ...) are shown too.  Slot 0 (the
; universal background color) is left alone: the game's $3F00 writes set it directly.
LoadPaletteColors
            lda   PAL_CELLS,y
            pha                       ; 1,s = slot map
            ldy   #31                 ; Backwards, so the BG colors win a shared slot
:loop       lda   (1,s),y
            and   #$00FF
            cmp   #$00FF
            beq   :next               ; not shown
            pha                       ; 1,s = slot * 2
            tyx
            ldal  PPU_MEM+$3F00,x
            jsr   NES_ColorToIIgs_X
            plx
            stal  SHR_PALETTES,x
:next       dey
            bpl   :loop
            pla
            rts

; DetectNESPalette
;
; X = the current palette id (0 = none).  Returns A = Y = the PAL_* id of the palette whose
; colors 1-3 are all in palette RAM (other than the reserved ones), or 0 if there is none (e.g. a
; step of a fade).  The current palette is tried first,
; then the palettes that follow it in the transitions, then the rest.
DetectNESPalette
            php
            rep   #$30
            stx   :from
            txa
            beq   :all
            jsr   :match              ; still the current palette?
            bcs   :found
            ldx   :from
            lda   PAL_SUCC,x          ; its successors, a 0-terminated list of ids
:snext      sta   :ptr
            tax
            lda:  0,x
            beq   :all
            tax
            jsr   :match
            bcs   :found
            lda   :ptr
            inc
            inc
            bra   :snext
:all        ldx   #2
:anext      jsr   :match
            bcs   :found
            inx
            inx
            cpx   #4
            bcc   :anext
            ldx   #0
:found      txy
            plp
            tya
            rts

; X = palette id.  Carry set if its colors are in palette RAM.  X is kept.  Only colors 1-3 of
; each group are compared (24 at most): color 0 is always IIgs slot 0.  One pass per group, from
; SP3 back to BG0, with its three colors compared inline.  NES colors are $00-$3F, so the $FF of a
; reserved or unused color is the only table byte with bit 7 set, and bmi skips it.
:match      phx
            lda   PAL_MATCH,x
            clc
            adc   #21
            tay                       ; Y -> the last group's 3 bytes
            ldx   #28                 ; X = the last group's palette RAM offset
            sep   #$20
            mx    %10
:group      lda:  0,y                 ; color 1
            bmi   *+8                 ; $FF = any value
            cmpl  PPU_MEM+$3F01,x
            bne   :mfail
            lda:  1,y                 ; color 2
            bmi   *+8
            cmpl  PPU_MEM+$3F02,x
            bne   :mfail
            lda:  2,y                 ; color 3
            bmi   *+8
            cmpl  PPU_MEM+$3F03,x
            bne   :mfail
            dey
            dey
            dey
            dex
            dex
            dex
            dex
            bpl   :group
            rep   #$20
            mx    %00
            plx
            sec
            rts
:mfail      rep   #$20
            plx
            clc
            rts

:from       ds    2
:ptr        ds    2

; id -> colors 1-3 of each group to match (BG0-BG3, SP0-SP3; $FF = any value: reserved or unused)
PAL_MATCH
            dw    0
            dw    PAL_GAME_MATCH
PAL_GAME_MATCH
            db    $00,$0F,$10,$00,$16,$10,$0F,$0F,$0F,$0F,$0F,$0F   ; BG0-BG3
            db    $0F,$00,$30,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F,$0F   ; SP0-SP3

; id -> the ids of the palettes that can follow it (transitions), 0-terminated
PAL_SUCC
            dw    PAL_NONE_SUCC
            dw    PAL_GAME_SUCC
PAL_NONE_SUCC
            dw    0
PAL_GAME_SUCC
            dw    0

; id -> swizzle tables (PALDATA segment, palettes.s)
PAL_SWIZZLE_LO
            dw    0
            dw    PAL_GAME_SWIZZLE
PAL_SWIZZLE_HI
            dw    0
            dw    ^PAL_GAME_SWIZZLE

; id -> slot map: for each NES palette RAM entry, the IIgs slot * 2, or $FF if it isn't loaded
; (color 0, which the game writes straight to slot 0, colors that share slot 0 with it, and
; approximated colors, which are shown in another color's slot)
PAL_CELLS
            dw    0
            dw    PAL_GAME_CELLS
PAL_GAME_CELLS
            db    $FF,$02,$FF,$04,$FF,$02,$06,$04,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; BG0-BG3
            db    $FF,$FF,$02,$08,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3

; from id -> its row of to id -> background groups to redraw (bit 0 = BG0 .. bit 3 = BG3).
; From no palette (0), everything is redrawn.
BG_UPDATE_MASKS
            dw    BG_UPDATE_MASKS_NONE
            dw    BG_UPDATE_MASKS_GAME
BG_UPDATE_MASKS_NONE
            dw    $0000,%1111
BG_UPDATE_MASKS_GAME
            dw    $0000
            dw    %0000   ; to game
